<?php declare(strict_types=1);require __DIR__.'/_bootstrap.php';require_admin();$pageTitle='Orders';$active='orders';$status=$_GET['status']??'';$q=trim((string)($_GET['q']??''));$where=[];$params=[];if(in_array($status,['new','contacted','completed','cancelled'],true)){$where[]='status=?';$params[]=$status;}if($q!==''){$where[]='(order_ref LIKE ? OR fullname LIKE ? OR phone LIKE ? OR fabric_type LIKE ?)';for($i=0;$i<4;$i++)$params[]='%'.$q.'%';}$sql='SELECT id,order_ref,fullname,phone,fabric_type,measurement,quantity,total_amount,status,payment_status,created_at FROM orders'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY id DESC LIMIT 200';$s=$pdo->prepare($sql);$s->execute($params);$orders=$s->fetchAll();require __DIR__.'/includes/layout.php';?><div class="panel"><div class="panel-head"><h2>Customer orders</h2><form class="filterbar"><input name="q" value="<?=e($q)?>" placeholder="Search order, customer, phone..."><select name="status"><option value="">All statuses</option><?php foreach(['new','contacted','completed','cancelled'] as $x): ?><option value="<?=$x?>" <?=$status===$x?'selected':''?>><?=ucfirst($x)?></option><?php endforeach;?></select><button class="btn btn-dark">Filter</button></form></div><div class="table-wrap"><table><thead><tr><th>Reference</th><th>Customer</th><th>Fabric</th><th>Measure</th><th>Qty</th><th>Total</th><th>Status</th><th>Payment</th><th></th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><?=e($o['order_ref'])?><br><small><?=e($o['created_at'])?></small></td><td><b><?=e($o['fullname'])?></b><br><small><?=e($o['phone'])?></small></td><td><?=e($o['fabric_type'])?></td><td><?=e($o['measurement']==='yard'?'Yard':'Trouser')?></td><td><?=e($o['quantity'])?></td><td><?=money($o['total_amount'])?></td><td><span class="badge <?=e($o['status'])?>"><?=e($o['status'])?></span></td><td><span class="badge <?=e($o['payment_status'])?>"><?=e($o['payment_status'])?></span></td><td><a class="btn btn-light" href="order.php?id=<?= (int)$o['id'] ?>">View</a></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/includes/footer.php';?>
